from pysat.solvers import Glucose3

# Let me use a simpler encoding and debug

def var(i, j, d):
    """Return SAT variable index for cell (i,j) with digit d (1-9)"""
    return i*9*9 + j*9 + d + 1

n = 9
solver = Glucose3()

# Each cell gets exactly one digit
for i in range(n):
    for j in range(n):
        vars_cell = [var(i, j, d) for d in range(1, 10)]
        solver.add_clause(vars_cell)
        for d1 in range(1, 10):
            for d2 in range(d1+1, 10):
                solver.add_clause([-var(i, j, d1), -var(i, j, d2)])

# Each row has each digit exactly once
for i in range(n):
    for d in range(1, 10):
        vars_row = [var(i, j, d) for j in range(n)]
        solver.add_clause(vars_row)
        for j1 in range(n):
            for j2 in range(j1+1, n):
                solver.add_clause([-var(i, j1, d), -var(i, j2, d)])

# Each column has each digit exactly once
for j in range(n):
    for d in range(1, 10):
        vars_col = [var(i, j, d) for i in range(n)]
        solver.add_clause(vars_col)
        for i1 in range(n):
            for i2 in range(i1+1, n):
                solver.add_clause([-var(i1, j, d), -var(i2, j, d)])

# Each 3x3 block has each digit exactly once
for bi in range(3):
    for bj in range(3):
        for d in range(1, 10):
            cells = []
            for di in range(3):
                for dj in range(3):
                    i = bi*3 + di
                    j = bj*3 + dj
                    cells.append(var(i, j, d))
            solver.add_clause(cells)
            for idx1 in range(9):
                for idx2 in range(idx1+1, 9):
                    solver.add_clause([-cells[idx1], -cells[idx2]])

# Fixed assignments
fixed = {
    2: 3,    # x[2]=3
    11: 6,   # x[11]=6
    13: 8,   # x[13]=8
    20: 9,   # x[20]=9
    22: 2,   # x[22]=2
    35: 7,   # x[35]=7
    42: 2,   # x[42]=2
    46: 9,   # x[46]=9
    50: 4,   # x[50]=4
    57: 6,   # x[57]=6
    58: 4,   # x[58]=4
    60: 9,   # x[60]=9
    62: 8,   # x[62]=8
    69: 5,   # x[69]=5
    78: 6,   # x[78]=6
    79: 4    # x[79]=4
}

for idx, val in fixed.items():
    i = idx // 9
    j = idx % 9
    solver.add_clause([var(i, j, val)])

# Let me check if the solver is actually solving correctly
# by first checking a simple unit clause
print("Checking var(0,2,3) =", var(0,2,3))
print("Checking var(0,2,4) =", var(0,2,4))

# Let me also add a check - let's see what the solver says about these variables
result = solver.solve()
print("Result:", result)

if result:
    model = solver.get_model()
    # Check what the model says about cell (0,2)
    for d in range(1, 10):
        v = var(0,2,d)
        print(f"  var(0,2,{d}) = {v} -> {'True' if v in model else 'False'}")

    # Also check cell (1,2)
    for d in range(1, 10):
        v = var(1,2,d)
        print(f"  var(1,2,{d}) = {v} -> {'True' if v in model else 'False'}")

    # Let me also check if the model satisfies the fixed clauses
    print("\nChecking fixed assignments in model:")
