            print(f"  x[{idx}] = {val} at ({i},{j}): OK (var {v} is True)")
        else:
            print(f"  x[{idx}] = {val} at ({i},{j}): FAIL (var {v} is False)")

    # Let me also check what values are assigned to each fixed cell
    print("\nValues assigned to fixed cells:")
