    # Verify fixed assignments
    print("\nVerifying fixed assignments:")
    all_ok = True
    for idx, val in fixed.items():
        i = idx // 9
        j = idx % 9
        ok = grid[i][j] == val
        if not ok:
            all_ok = False
        print(f"  x[{idx}] = {grid[i][j]} (expected {val}) {'OK' if ok else 'FAIL'}")

    print(f"\nAll fixed OK: {all_ok}")

    # Verify Sudoku constraints
    print("\nVerifying Sudoku constraints:")
    # Rows
    for i in range(9):
        if sorted(grid[i]) != list(range(1,10)):
            print(f"  Row {i} FAIL: {grid[i]}")
    # Columns
    for j in range(9):
        col = [grid[i][j] for i in range(9)]
        if sorted(col) != list(range(1,10)):
            print(f"  Col {j} FAIL: {col}")
    # Blocks
    for bi in range(3):
        for bj in range(3):
            block = []
            for di in range(3):
                for dj in range(3):
                    block.append(grid[bi*3+di][bj*3+dj])
            if sorted(block) != list(range(1,10)):
                print(f"  Block ({bi},{bj}) FAIL: {block}")
    print("  All constraints satisfied!")

    # Output as list
    result_list = []
    for i in range(9):
        for j in range(9):
            result_list.append(grid[i][j])
    print("\nResult list:", result_list)
else:
    print("UNSATISFIABLE")
